    static Map<String,Object> prepare(Map<String,Object> data,LocalDate today)throws Exception {Path file=root.resolve("library-"+(++sequence)+".json");CityPlanningReference.prepare(data,file,today);Map<String,Object> loaded=m(CityPlanningReference.load(file));ok(!loaded.containsKey("load_status"),"actual load "+loaded);eq(loaded,data,"load content");return loaded;}
