    static Map<String,Object> ready(Map<String,Object> data)throws Exception {Map<String,Object> result=lookup(prepare(data,TODAY),TODAY);eq(result.get("status"),"planning_reference","protected lookup accepts curated values");eq(result.get("verification_method"),CuratedCityDuration.METHOD,"method visible");eq(result.get("protected_envelope_validated"),true,"outer envelope marker");eq(result.get("semantic_annotations_are_language_proof"),false,"not NLP proof");for(String f:List.of("time_score_applicable","transport_verified","air_fallback_trigger","rail_exclusion_complete"))eq(result.get(f),false,"no stronger capability "+f);for(String leg:List.of("outbound","inbound")){Map<String,Object> value=m(result.get(leg));ok(!value.containsKey("reference_value_minutes_internal")&&!value.containsKey("policy_adjusted_minutes_internal"),"internal scalar removed");Map<String,Object> typed=m(value.get("source_duration"));for(String field:List.of("token","service_id","departure_clock","arrival_clock"))ok(!typed.containsKey(field),"private source role not copied into caller output");}return result;}
    static Map<String,Object> revoked(Map<String,Object> input){Map<String,Object> data=copy(input);data.put("library_revision",2);Map<String,Object> chain=m(l(data.get("references")).get(0)),e=m(l(chain.get("revisions")).get(0)),s=copy(e.get("snapshot"));s.put("version",2);s.put("status","revoked");l(chain.get("revisions")).add(obj("snapshot",s,"previous_hash",e.get("event_sha256"),"change_reason","Synthetic revocation after expiry"));rehash(data);return data;}
