        for(String scope:List.of("county","unknown","unknown_connection"))rejected(bundle(CuratedCityDurationTest.both(clockOut,f->m(CuratedCityDurationTest.c(f).get("endpoint_scope")).put("from",scope)),clockBack),"county_or_unknown_endpoint_scope");
        rejected(bundle(CuratedCityDurationTest.both(scalar(false,"reported_minutes","90分钟",90),f->CuratedCityDurationTest.c(f).put("verification_method","unknown_v2")),back),"verification_method_mismatch");
        rejected(bundle(CuratedCityDurationTest.change(scalar(false,"reported_minutes","90分钟",90),f->CuratedCityDurationTest.c(f).remove("verification_method"),f->{}),back),"verification_method_mismatch");
        rejected(bundle(CuratedCityDurationTest.change(scalar(false,"reported_minutes","90分钟",90),f->CuratedCityDurationTest.dur(f).put("value",91),f->{}),back),"core_read_disagreement");
