        for(int n:List.of(209,210,227,239,240,241)){Map<String,Object> data=bundle(scalar(false,"reported_minutes","60分钟",60),scalar(true,"approximate","约"+n+"分钟",n));Map<String,Object> q=lookup(prepare(data,TODAY),TODAY);eq(q.get("status"),n<240?"planning_reference":"planning_pending","each unbuffered directional reference strictly below240");if(n>=240)ok(!q.containsKey("planning_band_id"),"boundary cannot carry available band");}
