        DispatchPreference pref=DispatchPreference.from(Map.of("training_province","上海","training_city","上海","training_mode","线下"),null);
        for(int maximum:List.of(60,89,90,120,121,180,239,240)){Map<String,Object> fit=obj("local_priority",false,"planning_reference",limit,"route_reference",obj("status","rail_reference_pending","eligibility","unknown","missing_directions",List.of("synthetic missing strict proof")));eq(CityPlanningSelection.include(fit,pref,maximum),maximum>=90,"custom cutoff uses original typed exclusive upper edge");}
        Map<String,Object> last=ready(bundle(scalar(false,"reported_minutes","227分钟",227),scalar(true,"reported_minutes","227分钟",227)));
        for(int maximum:List.of(180,210,227,228,239,240))eq(CityPlanningSelection.underConfiguredLimit(last,maximum),maximum>227,"227-minute reference uses user cutoff without hidden 30 minutes: "+maximum);
