        eq(CityPlanningSelection.underConfiguredLimit(open,240),true,"exclusive240 bound allows planning");eq(CityPlanningSelection.underConfiguredLimit(open,239),false,"exclusive240 does not establish a smaller user limit");
        Map<String,Object> exactOpen=ready(bundle(CuratedCityDurationTest.fixture(false,CuratedCityDurationTest.upper("不到227分钟",227,false)),back));
