        Map<String,Object> withdrawn=revoked(initial);CityPlanningReference.continuation(CityPlanningReference.anchor(initial),withdrawn);Map<String,Object> retained=prepare(withdrawn,TODAY.plusDays(91));eq(lookup(retained,TODAY.plusDays(91)).get("reason"),"reference_revoked","expired history can be legitimately revoked");eq(m(l(m(l(retained.get("references")).get(0)).get("revisions")).get(0)),m(l(m(l(initial.get("references")).get(0)).get("revisions")).get(0)),"historical event untouched");
        var ended=CuratedCityDurationTest.both(scalar(false,"reported_minutes","90分钟",90),f->{CuratedCityDurationTest.c(f).put("effective_on","2026-08-01");CuratedCityDurationTest.c(f).put("effective_until","2026-08-31");});Map<String,Object> endData=prepare(bundle(ended,back),TODAY);eq(lookup(endData,TODAY).get("reason"),"source_period_ended","ended period retained structurally");
